const tasks = $('MB: Read tasks due today').all().map((i) => i.json).filter((r) => r && r.id);
const commitments = $('MB: Read open commitments').all().map((i) => i.json).filter((r) => r && r.id);
const overnightRow = $('MB: Read overnight count').first().json || {};
const overnightCount = parseInt(overnightRow.count, 10) || 0;
const urgent = $('MB: Read unhandled urgent').all().map((i) => i.json).filter((r) => r && r.id);

const taskLines = tasks.length ? tasks.map((t) => `- ${t.task_text}`).join('\n') : '(none)';
const commitmentLines = commitments.length
  ? commitments.map((c) => `- ${c.text} (${c.direction})`).join('\n')
  : '(none)';
const urgentLines = urgent.length ? urgent.map((u) => `- ${u.subject}`).join('\n') : '(none)';

const text = `<b>Morning Brief</b>\n\nTasks due today:\n${taskLines}\n\nOpen commitments:\n${commitmentLines}\n\nOvernight emails: ${overnightCount}\n\nUnhandled urgent:\n${urgentLines}`;
return [{ json: { text } }];

// FR15/spec.md 'multiple allowlisted chat IDs': every allowlisted chat gets
// the same digest. No dedup write for digests -- the Schedule Trigger
// already fires exactly once per day by construction.
const text = $json.text;
const allowedChatIds = ($env.TELEGRAM_ALLOWED_CHAT_IDS || '')
  .split(',')
  .map((id) => id.trim())
  .filter((id) => id.length > 0);

return allowedChatIds.map((chatId) => ({ json: { chat_id: chatId, text } }));

// AC6/AC10: cross candidates x allowlisted chat IDs, then drop any pair
// already present in bot_notifications -- this IS the dedup enforcement
// point (the INSERT below is a guard against a race, not the primary check).
const candidates = $('UP: Read urgent/VIP candidates').all().map((i) => i.json).filter((r) => r && r.id);
const sent = $('UP: Read existing alerts').all().map((i) => i.json).filter((r) => r && r.chat_id);
const sentKeys = new Set(sent.map((r) => `${r.chat_id}::${r.email_id}`));

const allowedChatIds = ($env.TELEGRAM_ALLOWED_CHAT_IDS || '')
  .split(',')
  .map((id) => id.trim())
  .filter((id) => id.length > 0);

const items = [];
for (const candidate of candidates) {
  for (const chatId of allowedChatIds) {
    if (!sentKeys.has(`${chatId}::${candidate.id}`)) {
      items.push({ json: { chat_id: chatId, email_id: candidate.id, subject: candidate.subject } });
    }
  }
}
return items;

// AC7/AC10: same candidate x chat_id x dedup-snapshot pattern as
// 'UP: Expand unsent alerts'.
const candidates = $('DN: Read due/overdue tasks').all().map((i) => i.json).filter((r) => r && r.id);
const sent = $('DN: Read existing nudges').all().map((i) => i.json).filter((r) => r && r.chat_id);
const sentKeys = new Set(sent.map((r) => `${r.chat_id}::${r.task_id}`));

const allowedChatIds = ($env.TELEGRAM_ALLOWED_CHAT_IDS || '')
  .split(',')
  .map((id) => id.trim())
  .filter((id) => id.length > 0);

const items = [];
for (const candidate of candidates) {
  for (const chatId of allowedChatIds) {
    if (!sentKeys.has(`${chatId}::${candidate.id}`)) {
      items.push({
        json: {
          chat_id: chatId,
          task_id: candidate.id,
          task_text: candidate.task_text,
          deadline: candidate.deadline,
        },
      });
    }
  }
}
return items;

const done = $('ER: Read done today').all().map((i) => i.json).filter((r) => r && r.id);
const slipped = $('ER: Read still open today').all().map((i) => i.json).filter((r) => r && r.id);
const tomorrow = $('ER: Read due tomorrow').all().map((i) => i.json).filter((r) => r && r.id);

const doneLines = done.length ? done.map((t) => `- ${t.task_text}`).join('
') : '(none)';
const slippedLines = slipped.length ? slipped.map((t) => `- ${t.task_text}`).join('
') : '(none)';
const tomorrowLines = tomorrow.length ? tomorrow.map((t) => `- ${t.task_text}`).join('
') : '(none)';

const text = `<b>Evening Review</b>

Done today:
${doneLines}

Due today, still open:
${slippedLines}

Due tomorrow:
${tomorrowLines}`;
return [{ json: { text } }];

